package orders

import "net/http"

// requireAuth rejects a request without a valid caller before any route
// runs.
func requireAuth(next http.Handler) http.Handler {
	return http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
		if callerFrom(r) == "" {
			http.Error(w, "unauthorized", http.StatusUnauthorized)
			return
		}
		next.ServeHTTP(w, r)
	})
}

func Routes(s *Service) http.Handler {
	mux := http.NewServeMux()
	mux.HandleFunc("GET /v2/orders/{id}", s.getOrder)
	mux.HandleFunc("GET /v2/orders", s.listOrders)
	mux.HandleFunc("POST /v2/orders", s.createOrder)
	return requireAuth(mux)
}

package orders

import (
	"encoding/json"
	"net/http"
)

func (s *Service) listOrders(w http.ResponseWriter, r *http.Request) {
	orders, err := s.store.OrdersOf(r.Context(), callerFrom(r))
	if err != nil {
		http.Error(w, "internal error", http.StatusInternalServerError)
		return
	}
	_ = json.NewEncoder(w).Encode(orders)
}
